  1→import { Plugin, PluginSettingTab, App, Setting, Modal, Notice } from 'obsidian';
  2→import { GraphData, PaperNode, Dimension } from './types/Paper';
  3→import { Graph3D } from './visualizations/3DGraph';
  4→
  5→/**
  6→ * Settings interface for the 3D Graph plugin
  7→ * Persisted to disk and loaded on plugin startup
  8→ */
  9→interface GraphPluginSettings {
 10→  /** Node size scaling: 'small' (0.5x-1.0x), 'medium' (0.75x-1.5x), 'large' (1.0x-2.0x) */
 11→  nodeScaling: 'small' | 'medium' | 'large';
 12→
 13→  /** Label visibility: 'on' (always), 'hover' (on mouse over), 'off' (never) */
 14→  labelVisibility: 'on' | 'hover' | 'off';
 15→
 16→  /** Physics simulation speed: 'slow' (stable), 'normal' (balanced), 'fast' (quick) */
 17→  physicsSpeed: 'slow' | 'normal' | 'fast';
 18→
 19→  /** Color palette: 'default', 'colorblind', 'bw' */
 20→  colorPalette: string;
 21→
 22→  /** Performance mode: 'high' (>30 FPS, full quality), 'low' (<30 FPS, battery friendly) */
 23→  performanceMode: 'high' | 'low';
 24→
 25→  /** Phase 5 Settings: Decision visualization */
 26→  showDecisionNodes: boolean;
 27→  showCascadeOverlay: boolean;
 28→  cascadeDepth: number; // 1-5
 29→  confidenceThreshold: number; // 0.0-1.0
 30→}
 31→
 32→/** Default plugin settings - used on first install */
 33→const DEFAULT_SETTINGS: GraphPluginSettings = {
 34→  nodeScaling: 'medium',
 35→  labelVisibility: 'hover',
 36→  physicsSpeed: 'normal',
 37→  colorPalette: 'default',
 38→  performanceMode: 'high',
 39→  showDecisionNodes: true,
 40→  showCascadeOverlay: false,
 41→  cascadeDepth: 3,
 42→  confidenceThreshold: 0.6,
 43→};
 44→
 45→/**
 46→ * Main plugin class for 3D Graph Visualization in Obsidian
 47→ * Handles plugin lifecycle, settings management, and UI registration
 48→ *
 49→ * @example
 50→ * // Users can:
 51→ * // 1. Click ribbon icon to open 3D graph
 52→ * // 2. Use command palette (Ctrl+P > "Open 3D Graph")
 53→ * // 3. Customize settings in Settings tab
 54→ */
 55→export default class GraphPlugin extends Plugin {
 56→  /** Current plugin settings (persisted across sessions) */
 57→  settings: GraphPluginSettings;
 58→
 59→  /**
 60→   * Called when plugin is loaded by Obsidian
 61→   * Sets up ribbon icons, commands, and settings tabs
 62→   */
 63→  async onload(): Promise<void> {
 64→    await this.loadSettings();
 65→
 66→    // Register ribbon icon in left sidebar - 3D Graph
 67→    this.addRibbonIcon('network', '3D Graph', () => {
 68→      this.openGraph3D();
 69→    });
 70→
 71→    // Register ribbon icon - Decision Explorer (NEW in Phase 5)
 72→    this.addRibbonIcon('lightbulb', 'Decision Explorer', () => {
 73→      this.openDecisionExplorer();
 74→    });
 75→
 76→    // Register command for command palette - 3D Graph
 77→    this.addCommand({
 78→      id: 'open-3d-graph',
 79→      name: 'Open 3D Graph',
 80→      callback: () => {
 81→        this.openGraph3D();
 82→      },
 83→    });
 84→
 85→    // Register command - Decision Explorer (NEW in Phase 5)
 86→    this.addCommand({
 87→      id: 'open-decision-explorer',
 88→      name: 'Open Decision Explorer',
 89→      hotkeys: [
 90→        {
 91→          modifiers: ['Ctrl', 'Shift'],
 92→          key: 'd',
 93→        },
 94→      ],
 95→      callback: () => {
 96→        this.openDecisionExplorer();
 97→      },
 98→    });
 99→
100→    // Register settings tab in plugin settings
101→    this.addSettingTab(new GraphSettingTab(this.app, this));
102→
103→    console.log('3D Graph Plugin loaded (Phase 5: Decision Explorer integrated)');
104→  }
105→
106→  /**
107→   * Open the 3D graph modal with graph data
108→   * Loads graph data and displays it in a new modal window
109→   *
110→   * @private
111→   * @returns {Promise<void>}
112→   * @throws Will show notice if graph fails to load
113→   */
114→  private async openGraph3D(): Promise<void> {
115→    try {
116→      // Create sample graph data for demonstration
117→      const graphData = this.generateSampleGraphData();
118→
119→      const modal = new Graph3D(this.app);
120→      await modal.loadGraphData(graphData);
121→      modal.open();
122→    } catch (error) {
123→      console.error('Failed to open 3D graph:', error);
124→      new Notice('Error opening 3D graph. Check console for details.');
125→    }
126→  }
127→
128→  /**
129→   * Open the Decision Explorer modal
130→   * Displays decision search, reasoning chains, cascades, and contradictions
131→   *
132→   * NEW in Phase 5: Integrated with 3D Graph for unified decision intelligence
133→   *
134→   * @param {string} paperFilter Optional paper title to filter decisions by
135→   * @private
136→   * @returns {Promise<void>}
137→   */
138→  private async openDecisionExplorer(paperFilter?: string): Promise<void> {
139→    try {
140→      // Import DecisionExplorerModal dynamically to avoid circular dependencies
141→      const { DecisionExplorerModal } = await import('./ui/DecisionExplorerModal');
142→
143→      const modal = new DecisionExplorerModal(this.app, paperFilter);
144→      modal.open();
145→      const msg = paperFilter
146→        ? `Decision Explorer opened (filtered for "${paperFilter}")`
147→        : 'Decision Explorer opened. Search for decisions or view reasoning chains.';
148→      new Notice(msg);
149→    } catch (error) {
150→      console.error('Failed to open Decision Explorer:', error);
151→      new Notice('Error opening Decision Explorer. Check console for details.');
152→    }
153→  }
154→
155→  /**
156→   * Generate sample graph data (84 papers) for testing
157→   * Creates synthetic papers with random dimensions and connections
158→   *
159→   * @private
160→   * @returns {GraphData} Complete graph with 84 nodes and ~250 edges
161→   * @note TODO: Replace with actual DataLoader that reads from vault
162→   */
163→  private generateSampleGraphData(): GraphData {
164→    const papers: PaperNode[] = [];
165→
166→    // Generate 84 sample papers
167→    for (let i = 0; i < 84; i++) {
168→      const paper: PaperNode = {
169→        id: `paper-${i}`,
170→        title: `Paper ${i + 1}: Research on AI and Knowledge Graphs`,
171→        path: `/papers/paper-${i}.md`,
172→        authors: [`Author ${i}`, `CoAuthor ${i}`],
173→        year: 2020 + Math.floor(i / 10),
174→        dimensions: {
175→          connectivity: Math.random(),
176→          conceptual_depth: Math.random(),
177→          temporal: Math.random(),
178→          cross_domain: (i % 15) + 1,
179→          completion: Math.random() * 100,
180→          recency: Math.random(),
181→          semantic_similarity: Math.random() * 0.5,
182→          similar_papers: [],
183→        },
184→      };
185→      papers.push(paper);
186→    }
187→
188→    // Generate edges (connections)
189→    const edges = [];
190→    for (let i = 0; i < papers.length; i++) {
191→      // Each paper connects to 3-5 random others
192→      const connectionCount = 3 + Math.floor(Math.random() * 3);
193→      for (let j = 0; j < connectionCount; j++) {
194→        const target = Math.floor(Math.random() * papers.length);
195→        if (target !== i) {
196→          edges.push({
197→            source: papers[i].id,
198→            target: papers[target].id,
199→            similarity: Math.random() * 0.5 + 0.5,
200→          });
201→        }
202→      }
203→    }
204→
205→    return {
206→      nodes: papers,
207→      edges: edges,
208→      metadata: {
209→        totalPapers: papers.length,
210→        totalEdges: edges.length,
211→        avgConnectivity: 0.5,
212→        domainDistribution: {},
213→        loadedAt: Date.now(),
214→      },
215→    };
216→  }
217→
218→  /**
219→   * Called when plugin is unloaded by Obsidian
220→   * Clean up resources and listeners
221→   */
222→  onunload(): void {
223→    console.log('3D Graph Plugin unloaded');
224→  }
225→
226→  /**
227→   * Load plugin settings from Obsidian's data.json
228→   * Falls back to DEFAULT_SETTINGS if no saved settings exist
229→   *
230→   * @returns {Promise<void>}
231→   */
232→  async loadSettings(): Promise<void> {
233→    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
234→  }
235→
236→  /**
237→   * Save plugin settings to Obsidian's data.json
238→   * Called automatically when user changes settings
239→   *
240→   * @returns {Promise<void>}
241→   */
242→  async saveSettings(): Promise<void> {
243→    await this.saveData(this.settings);
244→  }
245→}
246→
